import { websiteCount_overView } from '../../utils/demoAnalyticsData'
import {  WEBSITE_POST_LIST_DATA, WEBSITE_POST_LIST_LOADER, WEBSITE_OVERVIEW_DATA, WEBSITE_OVERVIEW_LOADER,  } from '../keys'

const initialState = { websiteOverview_data: websiteCount_overView, websiteOverview_loader: true , websitePost_data: [], websitePost_loader: true }

export default function reducer(state = initialState, action) {
    switch (action.type) {
        case WEBSITE_OVERVIEW_DATA: { return { ...state, websiteOverview_data: action.payload } }
        case WEBSITE_OVERVIEW_LOADER: { return {...state, websiteOverview_loader: action.payload} }  
        case WEBSITE_POST_LIST_DATA: { return { ...state, websitePost_data: action.payload } }
        case WEBSITE_POST_LIST_LOADER: { return {...state, websitePost_loader: action.payload} }  
        default: return { ...state }
    }
}