import axios from "axios"
import { BASE_URL } from "./api"


export const redirect_uri = `${BASE_URL}/feeds/authCallback/`
export const FB_ID = process.env.REACT_APP_FB_APP_ID
export const FB_SECRET = process.env.REACT_APP_FB_APP_SECRET
export const FB_SCOPE = (networkId) => networkId == 3 ? "user_posts,pages_show_list,pages_manage_metadata,pages_read_engagement,pages_read_user_content" : "business_management,instagram_manage_insights,instagram_manage_comments,pages_read_engagement,pages_read_user_content,pages_manage_metadata,pages_show_list,email,public_profile,instagram_basic"
export const FB_URL = (code) => `https://graph.facebook.com/v15.0/oauth/access_token?client_id=${FB_ID}&redirect_uri=${redirect_uri}&client_secret=${FB_SECRET}&code=${code}`
export const FB_AUTH_URL = (networkId) => `https://www.facebook.com/v15.0/dialog/oauth?client_id=${FB_ID}&redirect_uri=${redirect_uri}&state=facebook&scope=${FB_SCOPE(networkId)}`


export const GOOGLE_REDIRECT_URL = `${BASE_URL}/feeds/authCallback`
export const GOOGLE_ID = process.env.REACT_APP_GG_APP_ID
export const GOOGLE_SECRET = process.env.REACT_APP_GG_KEY
export const GOOGLE_URL = "https://oauth2.googleapis.com/token"
export const GOOGLE_SCOPE = "https://www.googleapis.com/auth/userinfo.email https://www.googleapis.com/auth/userinfo.profile https://www.googleapis.com/auth/business.manage openid https://www.googleapis.com/auth/business.manage"
export const GOOGLE_AUTH_URL = `https://accounts.google.com/o/oauth2/auth/oauthchooseaccount?response_type=code&redirect_uri=${GOOGLE_REDIRECT_URL}&client_id=${GOOGLE_ID}&scope=${GOOGLE_SCOPE}&access_type=offline&approval_prompt=force&state=google&service=lso&o2v=1&flowName=GeneralOAuthFlow`

export const INSTAGRAM_ID = process.env.REACT_APP_INSTAGRAM_APP_ID
export const INSTAGRAM_SECRET = process.env.REACT_APP_INSTAGRAM_APP_SECRET
export const INSTAGRAM_URL = "https://cors.bridged.cc/https://api.instagram.com/oauth/access_token"

export const CORS_API_KEY = process.env.REACT_APP_CORS_API_KEY

export const TWITTER_KEY = process.env.REACT_APP_TWITTER_API_KEY
export const TWITTER_SCOPE = "tweet.read%20users.read%20follows.read%20follows.write%20offline.access%20list.read%20like.read"
export const TWITTER_AUTH_URL = `https://twitter.com/i/oauth2/authorize?response_type=code&client_id=${TWITTER_KEY}&redirect_uri=${redirect_uri}&scope=${TWITTER_SCOPE}&state=twitter&code_challenge=challenge&code_challenge_method=plain`


export const FACEBOOK = async (code) => axios.get(FB_URL(code));

export const GOOGLE_AUTH_TOKEN = async (code) => {
    try {
        const payload = {
            code: code,
            client_id: GOOGLE_ID,
            client_secret: GOOGLE_SECRET,
            redirect_uri: GOOGLE_REDIRECT_URL,
            access_type: "offline",
            grant_type: "authorization_code"
        }
        return axios.post(`https://oauth2.googleapis.com/token`, payload)
    }
    catch (ex) {

    }
}

export const INSTAGRAM = async (code) => {
    // const data = {
    //     client_id: '480810795949098',
    //     client_secret: '48c75d71ec8faf89c59b6f4d69bccb89',
    //     grant_type: 'authorization_code',
    //     redirect_uri: redirect_uri,
    //     code: code
    // };

    var data = new FormData();
    data.append('client_id', INSTAGRAM_ID);
    data.append('client_secret', INSTAGRAM_SECRET);
    data.append('grant_type', 'authorization_code');
    data.append('redirect_uri', redirect_uri);
    data.append('code', code);

    const headers = {
        "Content-Type": "application/x-www-form-urlencoded",
        "x-cors-grida-api-key": CORS_API_KEY
    };

    return axios.post(INSTAGRAM_URL, data, { headers });
}

export const GET_INSTA_USERDATA = async (access_token) => {
    const reqUrl = `https://graph.instagram.com/me?fields=username&access_token=${access_token}`;
    const { data } = await axios.get(reqUrl);
    return data || {}
}

export const GET_FB_USER_DATA = async (access_token, appSecretProof) => {
    const reqUrl = `https://graph.facebook.com/v15.0/me?access_token=${access_token}&appsecret_proof=${appSecretProof}`;
    const { data } = await axios.get(reqUrl);
    return data || {}
}

export const GET_GOOGLE_DATA = async (token) => {
    return axios.get('https://www.googleapis.com/oauth2/v3/userinfo', { headers: { Authorization: `Bearer ${token}` }, });
}

export const GET_GMC_AUTH = async (code) => {
    const payload = {
        code,
        client_id: GOOGLE_ID,
        client_secret: GOOGLE_SECRET,
        redirect_uri: GOOGLE_REDIRECT_URL,
        access_type: "offline",
        grant_type: "authorization_code"
    };

    try {
        const response = await axios.post('https://oauth2.googleapis.com/token', payload);
        return response.data;
    } catch (error) {
        console.error('Failed to get GMC auth:', error);
        return {};
    }
}
