import HttpClient from "./http-client";
import { CREATE_SHOPON_API, UPDATE_SHOPON_API, DELETE_SHOPON_API, ALL_SHOPON_LIST_API, GET_POST, GET_SHOPON_WALL_API, SHOPON_SLUG_AVAILABILITY_API, GET_SHOPON_PRODUCT_API } from './api'
import { CREATE_SHOPON_REDUCER, UPDATE_SHOPON_REDUCER, DELETE_SHOPON_REDUCER, ALL_SHOPON_LIST_REDUCER, GET_SHOPON_WALL_REDUCER, ACTIVE_SHOPON_REDUCER, GET_SHOPON_PRODUCT_REDUCER, LOADING_SHOPON_REDUCER, SHOPON_BRAND_DATA_REDUCER } from '../reducer/keys';
import { TOAST_DISMISS, TOAST_ERROR, TOAST_SUCCESS } from '../utils';
import store from '../store';



export const CREATE_SHOPON = (name, callback, navigate) => {
    const { dashboardData } = store.getState()
    var obj = { "name": name }
    return (dispatch) => {
        new HttpClient().post(CREATE_SHOPON_API, obj).then((response) => {
            const { responseData, responseCode, responseStatus, responseMessage } = response.data
            if (responseCode == 200) {
                localStorage.setItem('shopOn_id', responseData?.id)
                TOAST_SUCCESS(responseMessage)
                dispatch({ type: CREATE_SHOPON_REDUCER, payload: responseData });
                dispatch({ type: ACTIVE_SHOPON_REDUCER, payload: responseData?.id });
                dispatch({ type: SHOPON_BRAND_DATA_REDUCER, payload: responseData });
                navigate(`/shopon-bio/preview/${localStorage.getItem('shopOn_id')}`)
                callback(responseCode, responseStatus);
            }
        }).catch(error => {
            const { data } = error.response;
            if (data.responseCode == 404) {
                TOAST_ERROR(data.responseMessage);
                callback(data.responseCode, data.responseMessage);
            }
            else {
                TOAST_ERROR("Something went wrong!")
            }
        });
    }
}

export const UPDATE_SHOPON = (obj, callback) => {
    return (dispatch) => {
        new HttpClient().post(UPDATE_SHOPON_API, obj).then((response) => {
            const { responseData, responseCode, responseStatus, responseMessage } = response.data
            if (responseCode == 200) {
                TOAST_SUCCESS(responseMessage)
                dispatch({ type: UPDATE_SHOPON_REDUCER, payload: { id: obj.id, responseData } });

                callback(responseCode, responseStatus);
            }
        }).catch(error => {
            const { data } = error.response;
            if (data.responseCode == 404) {
                TOAST_ERROR(data?.response_message);
                callback(data?.response_message);
            }
            else {
                callback(data.responseCode, data.responseStatus);
            }
        });
    }
}


export const DELETE_SHOPON = (id, callback, navigate) => {
    const { shopOnList } = store.getState().shopOnList
    return (dispatch) => {
        new HttpClient().delete(`${DELETE_SHOPON_API}/${id}`).then((response) => {
            const { responseData, responseCode, responseMessage } = response.data
            if (responseCode == 200) {
                TOAST_DISMISS()
                TOAST_SUCCESS(responseMessage)
                dispatch({ type: DELETE_SHOPON_REDUCER, payload: id });
                setTimeout(() => {
                    if (shopOnList && shopOnList?.length > 1) {
                        if (id == localStorage.getItem('shopOn_id')) {
                            if (shopOnList[0]?.id == id) {
                                localStorage.setItem('shopOn_id', shopOnList[1]?.id)
                                dispatch({ type: ACTIVE_SHOPON_REDUCER, payload: shopOnList[1]?.id });
                                navigate(`/shopon-bio/preview/${shopOnList[1]?.id}`)
                            }
                            else {
                                localStorage.setItem('shopOn_id', shopOnList[0]?.id)
                                dispatch({ type: ACTIVE_SHOPON_REDUCER, payload: shopOnList[0]?.id });
                                navigate(`/shopon-bio/preview/${shopOnList[0]?.id}`)
                            }
                        }

                    } else {
                        localStorage.setItem('shopOn_id', '')
                        dispatch({ type: ACTIVE_SHOPON_REDUCER, payload: '' });
                        navigate(`/shopon-bio/preview/`)
                    }
                }, 1000);
                callback(responseCode, responseMessage, "delete");
            }
        }).catch(error => {
            const { data } = error.response;
            TOAST_DISMISS();
            if (data.responseCode == 404) {
                TOAST_ERROR(data.responseMessage);
                callback(data.responseCode, data.responseMessage);
            }
            else {
                TOAST_ERROR("Something went wrong!")
            }
        });
    }
}

export const GET_ALL_SHOPON_LIST = () => {
    var allwalls = store.getState()?.dashboardData?.dashboarddata?.allWalls
    return (dispatch) => {
        new HttpClient().get(ALL_SHOPON_LIST_API).then((response) => {
            const { responseData, responseCode } = response.data
            if (responseCode == 200) {
                var webData = responseData?.find((x) => x.id == localStorage.getItem('shopOn_id'));

                if (!webData) {
                    webData = responseData && responseData[0] ? responseData[0].id : ''
                    localStorage.setItem('shopOn_id', webData)
                }
                else localStorage.setItem('shopOn_id', webData ? webData.id : '')
                dispatch({ type: SHOPON_BRAND_DATA_REDUCER, payload: webData });
                dispatch({ type: ALL_SHOPON_LIST_REDUCER, payload: responseData });
                dispatch({ type: LOADING_SHOPON_REDUCER, payload: true });
                dispatch({ type: ACTIVE_SHOPON_REDUCER, payload: localStorage.getItem('shopOn_id') });
            }
        })
    }
}


export const SHOPON_SLUG_AVAILABILITY = (obj) => new HttpClient().post(SHOPON_SLUG_AVAILABILITY_API, obj, { validateStatus: false })

export const CHANGE_SHOPON_WALL = (wallId, limit) => {
    return (dispatch) => {
        if (wallId) {

            dispatch({ type: LOADING_SHOPON_REDUCER, payload: true });
            localStorage.setItem('shopOnActive_wall', wallId);

            new HttpClient().get(`${GET_POST}/${wallId}`).then((wallReponseData) => {

                new HttpClient().get(`${GET_SHOPON_WALL_API}/${localStorage.getItem('shopOn_id')}`).then((response) => {
                    const { postData, responseCode, responseData } = response.data;
                    if (responseCode == 200) {
                        var updatedData = [];
                        wallReponseData?.data?.responseData?.map((item) => {
                            updatedData.push({ ...item, imageList: [], postFileNew: item.postFile })
                        })

                        const newData = { ...response.data, postData: updatedData || [], customPost: [], productSetting: responseData?.productSetting }
                        dispatch({ type: GET_SHOPON_WALL_REDUCER, payload: newData })
                    }
                    dispatch({ type: LOADING_SHOPON_REDUCER, payload: false })
                    //setTimeout(() => { ; }, 1000)
                    dispatch({ type: ACTIVE_SHOPON_REDUCER, payload: localStorage.getItem('shopOn_id') });
                    dispatch(CHANGE_SHOPON_PRODUCT(responseData.slug))
                }).catch((error) => {
                    console.log("ERROR", error)
                    dispatch({ type: LOADING_SHOPON_REDUCER, payload: false });
                });
            }).catch((error) => {
            });
        }
        else {
            dispatch({ type: LOADING_SHOPON_REDUCER, payload: false });
        }
    };

}

export const CHANGE_SHOPON_PRODUCT = (slug) => {
    return (dispatch) => {
        new HttpClient().get(`${GET_SHOPON_PRODUCT_API}/${slug}`).then((response) => {
            const { responseData, responseCode } = response.data;
            if (responseCode == 200) {
                dispatch({ type: GET_SHOPON_PRODUCT_REDUCER, payload: responseData?.products })
            }
        }).catch((error) => {
            console.log("ERROR", error)
        });
    };
}