import { DISPATCH_GET_ALL_THEME, DISPATCH_GET_WALL_DETAILS ,APPLYED_NEW_THEME } from './keys'
const initialState = { 
    themeList: [],
    details: [],
    activeTheme:null
}
export default function reducer(state = initialState, action) {
    switch (action.type) {
        case DISPATCH_GET_ALL_THEME: {
            return { ...state, themeList: action.payload }
        }
        case DISPATCH_GET_WALL_DETAILS: { 
            const id = action.payload?.wall?.Personalization.commerceTheme;
            return { ...state, details: action.payload, activeTheme: id}
        }
        case APPLYED_NEW_THEME:{
            return { ...state, activeTheme: action.payload }
        }
        default:
            return { ...state }
    }

}