import {
    MODERATION_GET_DATA, MODERATION_UPDATE_CHECK_ALL, MODERATION_PIN_UPDATE_STATUS, MODERATION_POST_STATUS_UPDATE, MODERATION_GET_DETAILS, MODERATION_FILTER_DATE_RANGES, MODERATION_FILTER_LIMIT, MODERATION_FILTER_PINNED, MODERATION_FILTER_TABS_STATUS, MODERATION_FILTER_SEARCH_TAGS, MODERATION_PAGINATE_UPDATE, MODERATION_EDIT_POST_LOADER, MODERATION_FILTER_BODY_POST_TAG,
    MODERATION_FILTER_BODY_SOCIAL_FEED,
    MODERATION_FILTER_BODY_POST_TYPE,
    MODERATION_FILTER_BODY_OTHER,
    MODERATION_FILTER_BODY_POST_TAG_REMOVE,
    MODERATION_FILTER_BODY_SOCIAL_FEED_REMOVE,
    MODERATION_FILTER_BODY_POST_TYPE_REMOVE,
    MODERATION_FILTER_BODY_OTHER_REMOVE,
    MODERATION_FILTER_BODY_REMOVE_ALL,
    MODERATION_FILTER_SEARCH_POST,
    MODERATION_FILTER_BODY_DATE_RANGES,
    MODERATION_FILTER_BODY_DATE_RANGES_REMOVE,
    MODERATION_FILTER_BODY_POST_TAG_EXTEND,
    MODERATION_CHECKED_DATA,
    MODERATION_CHECKED_DATA_REMOVE,
    MODERATION_CHECKED_DATA_REMOVE_ALL,
    MODERATION_CHECKED_DATA_STATUS,
    MODERATION_CHECKED_DATA_BULK,
    MODERATION_CHECKED_DATA_BULK_REMOVE,
    MODERATION_OFFSET_UPDATE, MODERATION_ENABLE_HOTSPOT,
    MODERATION_TAGG_PRODUCT, MODERATION_ALL_PRODUCT, MODERATION_UPDATE_HOTSPOT, MODERATION_REMOVE_TAG_PRODUCT, UGC_DATA, UGC_TEMPLATE_ADD, OPEN_UGC_POPUP, REMOVE_TEMPLATE, UPDATE_TEMPLATE, ADD_UGC_REQUEST_DATA, CLEAR_UGC_REQUEST_DATA, GET_LIST_ALL_PIN_TO_TOP_POST, CHANGE_MODERATION_WALLID, ON_POST_DATA_UPDATE_STATE,
    MODERATION_LODING,
    MODERATION_RESET
} from './keys'



const initialState = {
    filter: { feeds: [], postType: [], text: "", highlight: "", pinned: 0, recent: "", retweet: "", status: 0, offset_start: 0, postList: '', feedId:'', feedFilter: "",  startDate: "", endDate: "", limit: 50, tags: [], searchByTag: 0, }, 
    details: {privatepost:0, publicpost:0 ,totalpost:0}, 
    listData: [],
    total: 0, 
    isCheckedPostCount: 0,
     paginateData: {currentPage:1 , totalPages:1, pages:[]}, 
     isEditing: false,
    filterBody: { postTags: [], socialFeed: [], postType: [], other: [], dateRanges: {} },
    check_uncheck_all: { status: false, data: [] },
    searchData: [],
    taggProduct: [],
    addFeedNetworks: null,
    ugcData: {},
    ugcPopup: false,
    ugcRequestData: [],
    loding: true,
    pinToTop: null,
    taggProductChange: true,
    changeModeration_wall: false
}

export default function reducer(state = initialState, action) {
    switch (action.type) {
        case MODERATION_OFFSET_UPDATE: {
            var { filter } = state;
            filter["offset_start"] = action.payload;
            return { ...state, filter }
        }

        case MODERATION_CHECKED_DATA_BULK: {
            let { check_uncheck_all } = state;
            const { status, data } = action.payload;
            check_uncheck_all.status = status
            if (data && data.length > 0) {
                data.map((item) => {
                    const filterCount = check_uncheck_all.data.filter(x => x.id == item.id)
                    if (filterCount.length == 0) check_uncheck_all.data.push(item)
                })
            }
            return { ...state, check_uncheck_all }
        }
        case MODERATION_CHECKED_DATA_BULK_REMOVE: {
            let { check_uncheck_all } = state;
            const { status, data } = action.payload;
            check_uncheck_all.status = status
            if (data && data.length > 0) {
                data.map((item) => {
                    const filterFindIndex = check_uncheck_all.data.findIndex(x => x.id == item.id)
                    if (filterFindIndex > -1) {
                        check_uncheck_all.data.splice(filterFindIndex, 1);
                    }
                })
            }
            return { ...state, check_uncheck_all }
        }

        case MODERATION_CHECKED_DATA: {
            let { check_uncheck_all } = state;
            const { status, data } = action.payload;
            check_uncheck_all.status = status
            const filterCount = check_uncheck_all.data.filter(x => x.id == data.id)
            if (filterCount.length == 0) check_uncheck_all.data.push(data)
            return { ...state, check_uncheck_all }
        }
        case MODERATION_CHECKED_DATA_REMOVE: {
            let { check_uncheck_all } = state;
            const { status, data } = action.payload;
            check_uncheck_all.status = status
            const filterFindIndex = check_uncheck_all.data.findIndex(x => x.id == data.id)
            if (filterFindIndex > -1) {
                check_uncheck_all.data.splice(filterFindIndex, 1);
            }
            return { ...state, check_uncheck_all }
        }
        case MODERATION_CHECKED_DATA_REMOVE_ALL: {
            let { check_uncheck_all } = state;
            check_uncheck_all.status = false
            check_uncheck_all.data = []
            return { ...state, check_uncheck_all }
        }
        // case MODERATION_CHECKED_DATA_STATUS: {
        //     let { check_uncheck_all } = state;
        //     const { status } = action.payload;
        //     check_uncheck_all.status = status
        //     return { ...state, check_uncheck_all }
        // }

        case MODERATION_PAGINATE_UPDATE: {
            var { filter , paginateData} = state;
            let { currentPage, offset } = action.payload;
            filter["offset_start"] = offset || 0;
            paginateData.currentPage = currentPage || 1;
            return { ...state, paginateData, filter }
        }
 
        case MODERATION_FILTER_SEARCH_TAGS: {
            let { filter, filterBody } = state;
            //filter.text = action.payload;
            filter.searchByTag = 1;
            var filterdata = filter.tags.filter(word => word == `+${action.payload}`);
            if (filterdata && filterdata.length == 0) {
                if (!filter.tags.includes(`+${action.payload}`)) filter.tags.push(`+${action.payload}`)
            }
            else {
                const filterFindIndex = filter.tags.findIndex(x => x == `+${action.payload}`)
                if (filterFindIndex > -1) {
                    filter.tags.splice(filterFindIndex, 1);
                }

                const findIndex = filterBody.postTags.findIndex(x => x == action.payload)
                if (findIndex > -1) {
                    filterBody.postTags.splice(findIndex, 1);
                }
            }

            return { ...state, filter, filterBody }
        }
        case MODERATION_FILTER_SEARCH_POST: {
            let { filter } = state;
            filter.text = action.payload;
            filter.searchByTag = 0;
            // filter.tags.push(action.payload.tags)
            return { ...state, filter }
        }
        case MODERATION_FILTER_TABS_STATUS: {
            let { filter } = state;
            filter.status = action.payload;
            return { ...state, filter }
        }
        case MODERATION_FILTER_PINNED: {
            let { filter } = state;
            filter.pinned = action.payload;
            return { ...state, filter }
        }

        case MODERATION_FILTER_DATE_RANGES: {
            let { filter } = state;
            const { startDate, endDate } = action.payload
            filter.startDate = startDate;
            filter.endDate = endDate;
            return { ...state, filter }
        }
        case MODERATION_FILTER_LIMIT: {
            var { filter , paginateData} = state;
            filter.limit = action.payload;
            filter["offset_start"] = 0;
            paginateData.currentPage = 1;
            return { ...state, filter, paginateData }
        }
        case MODERATION_FILTER_DATE_RANGES: {
            let { filter } = state;
            const { startDate, endDate } = action.payload
            filter.startDate = startDate;
            filter.endDate = endDate;
            return { ...state, filter }
        }

        case MODERATION_GET_DATA: {
            let { filter , paginateData} = state;
            const { listData, total, page, offset } = action.payload
            // filter["offset_start"] = offset;
            let pageArr = Array.from({ length: page }, (v, k) => k + 1);
            paginateData.pages = pageArr
            paginateData.totalPages = page
            return { ...state, listData, total, paginateData, filter, loding: false, }
        }

        case MODERATION_UPDATE_CHECK_ALL: {
            const { listData, isCheckedPostCount } = action.payload
            return { ...state, listData, isCheckedPostCount }
        }

        
        case MODERATION_FILTER_BODY_POST_TAG_EXTEND: {
            const { filterBody } = state;
            if (!filterBody.postTags.includes(action.payload)) filterBody.postTags.push(action.payload)
            return { ...state, filterBody }
        }

        case MODERATION_FILTER_BODY_POST_TAG: {
            const { filter, filterBody } = state;
            filter.tags.push(`+${action.payload}`)
            filterBody.postTags.push(action.payload)
            return { ...state, filterBody, filter }
        }
        case MODERATION_FILTER_BODY_SOCIAL_FEED: {
            const { filter, filterBody } = state;
            const { value } = action.payload;
            filter.feedFilter = "1";
            filter.feeds.push(value)
            filterBody.socialFeed.push(action.payload)
            return { ...state, filterBody, filter }
        }
        case MODERATION_FILTER_BODY_POST_TYPE: {
            const { filter, filterBody } = state;
            filter.postType.push(action.payload)
            filterBody.postType.push(action.payload)
            return { ...state, filterBody, filter }
        }
        case MODERATION_FILTER_BODY_OTHER: {
            const { filter, filterBody } = state;
            const { key } = action.payload
            switch (key) {
                case "highlightFilter":
                    filter.highlight = 1;
                    break;
                case "pinFilter":
                    filter.pinned = 1;
                    break;
                case "recentFilter":
                    filter.recent = 1;
                    break;
                case "retweetsFilter":
                    filter.retweet = 1;
                    break;

                default:
                    break;
            }
            filterBody.other.push(action.payload)
            return { ...state, filterBody, filter }
        }

        case MODERATION_FILTER_BODY_POST_TAG_REMOVE: {
            const { filter, filterBody } = state;
            const { findIndex, value } = action.payload;
            if (findIndex > -1) {
                filterBody.postTags.splice(findIndex, 1);
            }
            if (filter.text && filter.text.length > 0 && String(filter.text).toLocaleLowerCase() == String(value).toLocaleLowerCase()) {
                filter.text = "";
            }
            const filterFindIndex = filter.tags.findIndex(x => x == `+${value}`)
            if (filterFindIndex > -1) {
                filter.tags.splice(filterFindIndex, 1);
            }
            return { ...state, filterBody, filter }
        }
        case MODERATION_FILTER_BODY_SOCIAL_FEED_REMOVE: {
            const { filter, filterBody } = state;
            const { findIndex, value } = action.payload;
            if (findIndex > -1) {
                filterBody.socialFeed.splice(findIndex, 1);
            }
            const filterFindIndex = filter.feeds.findIndex(x => x == value)
            if (filterFindIndex > -1) {
                filter.feeds.splice(filterFindIndex, 1);
            }
            if (filter.feeds && filter.feeds.length == 0) {
                filter.feedFilter = "";
            }
            return { ...state, filterBody, filter }
        }
        case MODERATION_FILTER_BODY_POST_TYPE_REMOVE: {
            const { filter, filterBody } = state;
            const { findIndex, value } = action.payload;
            if (findIndex > -1) {
                filterBody.postType.splice(findIndex, 1);
            }
            const filterFindIndex = filter.postType.findIndex(x => x == value)
            if (filterFindIndex > -1) {
                filter.postType.splice(filterFindIndex, 1);
            }
            return { ...state, filterBody, filter }
        }
        case MODERATION_FILTER_BODY_OTHER_REMOVE: {
            const { filter, filterBody } = state;
            const { findIndex } = action.payload;
            if (findIndex > -1) {
                filterBody.other.splice(findIndex, 1);
            }
            const { value } = action.payload
            switch (value) {
                case "highlightFilter":
                    filter.highlight = "";
                    break;
                case "pinFilter":
                    filter.pinned = 0;
                    break;
                case "recentFilter":
                    filter.recent = "";
                    break;
                case "retweetsFilter":
                    filter.retweet = "";
                    break;
                default:
                    break;
            }
            return { ...state, filterBody, filter }
        }

        case MODERATION_FILTER_BODY_REMOVE_ALL: {
            var { filter, filterBody } = state;
            filter.tags = [];
            filter.postType = [];
            filter.feeds = [];
            filter.highlight = "";
            filter.pinned = 0;
            filter.recent = "";
            filter.retweet = "";
            filter.startDate = ""; filter.endDate = "";
            filter.feedFilter = "";
            if (filter.text && filter.text.length > 0) filter.text = ""
            filterBody = { postTags: [], socialFeed: [], postType: [], other: [], dateRanges: {} }
            return { ...state, filterBody, filter }
        }
        case MODERATION_FILTER_BODY_DATE_RANGES: {
            const { filterBody } = state;
            const { startDate, endDate } = action.payload;
            filterBody.dateRanges = { startDate, endDate }
            return { ...state, filterBody }
        }
        case MODERATION_FILTER_BODY_DATE_RANGES_REMOVE: {
            const { filter, filterBody } = state;
            filterBody.dateRanges = {}
            filter.startDate = ""; filter.endDate = "";
            return { ...state, filterBody, filter }
        }
        case MODERATION_ALL_PRODUCT: { return { ...state, taggProduct: action.payload, taggProductChange: false } }
        
        case MODERATION_TAGG_PRODUCT: {
            const { product, referenceId, responseData } = action.payload;
            let { listData } = state;
            listData = updateProductList(product, referenceId, responseData, listData,)
            return { ...state, listData: listData }
        }
        case MODERATION_REMOVE_TAG_PRODUCT: {
            const { productId, referenceId } = action.payload;
            let { listData } = state;
            listData = removeTaged_product(productId, referenceId, listData)
            return { ...state, listData }
        }
        case MODERATION_ENABLE_HOTSPOT: {
            const { isHotspotEnable, referenceId } = action.payload;
            let { listData } = state;
            listData = enableHotspot(isHotspotEnable, referenceId, listData)
            return { ...state, listData: listData }

        }
        case MODERATION_UPDATE_HOTSPOT: {
            const { productId, referenceId, location_hotspot } = action.payload;
            let { listData } = state;
            listData = updateHotspot(productId, referenceId, location_hotspot, listData)
            return { ...state, listData: listData }

        }

        case UGC_DATA: { return { ...state, ugcData: action.payload } }
        case OPEN_UGC_POPUP: { return { ...state, ugcPopup: action.payload } }

        case UGC_TEMPLATE_ADD: {
            const { template } = state.ugcData
            const tempTemplate = [...template, action.payload]
            return { ...state, ugcData: { ...state.ugcData, template: tempTemplate } }
        }

        case REMOVE_TEMPLATE: {
            const { template } = state.ugcData
            const tmp = template.filter(t => t.id != action.payload)
            return { ...state, ugcData: { ...state.ugcData, template: tmp } }
        }

        case UPDATE_TEMPLATE: {
            const { template } = state.ugcData
            var tmp = template.filter(t => t.id != action.payload.id)
            const uData = action.payload
            return { ...state, ugcData: { ...state.ugcData, template: [...tmp, uData] } }
        }

        case MODERATION_LODING: { return { ...state, loding: true } }
        case MODERATION_RESET: { return { ...state, loding: true , listData:[]} }
        case MODERATION_GET_DETAILS: { return { ...state, details: action.payload } }
        case MODERATION_PIN_UPDATE_STATUS: { return { ...state, listData: action.payload } }
        case MODERATION_POST_STATUS_UPDATE: { return { ...state, listData: action.payload } }
        case MODERATION_EDIT_POST_LOADER: { return { ...state, isEditing: action.payload } }
        case ADD_UGC_REQUEST_DATA: { return { ...state, ugcRequestData: action.payload } }
        case CLEAR_UGC_REQUEST_DATA: { return { ...state, ugcRequestData: [] } }
        case GET_LIST_ALL_PIN_TO_TOP_POST: { return { ...state, pinToTop: action.payload } }
        case CHANGE_MODERATION_WALLID: { return { ...state, changeModeration_wall: action.payload } }
        case ON_POST_DATA_UPDATE_STATE: return { ...state, listData: updatePostArray(action.payload, action.postType, state.listData) }
        


        default:
            return { ...state }
    }

}

const updatePostArray = (data, postType, listData) => {
    const updatedListData = listData.map(item => {
        const updatedItem = data.find(d => item.id === d.id);
        if (updatedItem) {
            return { ...item, ...updatedItem, newMedia: updatedItem.postFile, mediaUrl: updatedItem.mediaFile, type: updatedItem.mediaFile ? '3' : '2' };
        } else {
            return item;
        }
    });
    return updatedListData;
}


const updateProductList = (product, referenceId, responseData, listData) => {
    let updatedProduct = listData;
    listData.map((item, index) => {
        if (item.referenceId == referenceId) {
            if (item.postproduct && item.postproduct.length > 0) {
                item.postproduct.push(responseData);
            }
            else {
                item.postproduct.push(responseData);
            }
        };
    })
    return updatedProduct;
}

const removeTaged_product = (productId, referenceId, listData) => {
    let updatedProduct = listData;
    listData.map((item) => {
        if (item.referenceId == referenceId) {
            item.postproduct = item.postproduct.filter(x => x.ugc_product !== productId)
        }
    })
    return updatedProduct;
}

const updateHotspot = (productId, referenceId, location_hotspot, listData) => {
    let updatedProduct = listData;
    listData.map((item) => {
        if (item.referenceId == referenceId) {
            item.postproduct.map((prd) => {
                if (prd.ugc_product == productId) prd.hotspot = location_hotspot;
            })
        }
    })
    return updatedProduct;
}

const enableHotspot = (isHotspotEnable, referenceId, listData) => {
    let updatedProduct = listData;
    listData.map((item) => {
        if (item.referenceId == referenceId) {
            item.hotspot = isHotspotEnable;
        }
    })
    return updatedProduct
}