import { PostType_PostNetwork } from '../../utils/demoAnalyticsData'
import { TOP_INFLUENCERS_LOADER, MOST_ACTIVE_CREATORS_LOADER, GET_TOP_INFLUENCERS, MOST_ACTIVE_CREATORS, TYPE_BY_POST_NETWORK, TYPE_BY_POST_NETWORK_LOADER, SENTIMENT_POST, SENTIMENT_POST_LOADER, WORD_CLOUD, WORD_CLOUD_LOADER, MENTION_POST, MENTION_POST_LOADER,  } from '../keys'

const initialState = {
    counts: [],
    counts_loader: true,

    most_active_users: { data: [], total: 0 },
    most_active_users_loader: true, 

    top_influential: { data: [], total: 0 },
    top_influential_loader: true,  

    type_by_post_network: PostType_PostNetwork,
    type_by_post_network_loader: true,

    word_cloud: [],
    word_cloud_loader: true,

    sentiment_by_post_statistics: [],
    sentiment_by_post_statistics_loader: true,

    post_by_mention: [],
    post_by_mention_loader: true
}
export default function reducer(state = initialState, action) {
    switch (action.type) {

        case MOST_ACTIVE_CREATORS: { return { ...state, most_active_users: action.payload } }
        case MOST_ACTIVE_CREATORS_LOADER: { return {...state, most_active_users_loader: action.payload} } 

        case GET_TOP_INFLUENCERS: { return { ...state, top_influential: action.payload } }
        case TOP_INFLUENCERS_LOADER: { return { ...state, top_influential_loader: action.payload} }

        case TYPE_BY_POST_NETWORK: { return { ...state, type_by_post_network: action.payload } }
        case TYPE_BY_POST_NETWORK_LOADER: { return { ...state, type_by_post_network_loader: action.payload} }

        case WORD_CLOUD: { return { ...state, word_cloud: action.payload } }
        case WORD_CLOUD_LOADER: { return { ...state, word_cloud_loader: action.payload} } 

        case SENTIMENT_POST: { return { ...state, sentiment_by_post_statistics: action.payload } }
        case SENTIMENT_POST_LOADER: { return { ...state, sentiment_by_post_statistics_loader: action.payload} }

        case MENTION_POST: { return { ...state, post_by_mention: action.payload } }
        case MENTION_POST_LOADER: { return { ...state, post_by_mention_loader: action.payload} }

        default:
            return { ...state }
    }

}