import {  WEBSITE_POST_LIST_DATA, WEBSITE_POST_LIST_LOADER, WEBSITE_OVERVIEW_DATA, WEBSITE_OVERVIEW_LOADER, IS_SHOPON_POST, SHOPON_CHART_DATA, SHOPON_CHART_LOADER, SHOPON_TOP_POST_DATA, SHOPON_TOP_POST_LOADER, SHOPON_TOP_PRODUCT_DATA, SHOPON_TOP_PRODUCT_LOADER,  } from '../keys'

const initialState = { shopOnOverview_data: [], shopOnOverview_loader: true , shopOntopProduct_data: [], shopOntopProduct_loader: true , shopOnTopPost_data: [], shopOnTopPost_loader: true , noPost:true  }

export default function reducer(state = initialState, action) {
    switch (action.type) {
        case SHOPON_CHART_DATA: { return { ...state, shopOnOverview_data: action.payload } }
        case SHOPON_CHART_LOADER: { return {...state, shopOnOverview_loader  : action.payload} }

        case SHOPON_TOP_PRODUCT_DATA: { return { ...state, shopOntopProduct_data: action.payload } }
        case SHOPON_TOP_PRODUCT_LOADER: { return {...state, shopOntopProduct_loader  : action.payload} }

        case SHOPON_TOP_POST_DATA: { return { ...state, shopOnTopPost_data: action.payload } }
        case SHOPON_TOP_POST_LOADER: { return {...state, shopOnTopPost_loader  : action.payload} }
    
        case IS_SHOPON_POST: { return { ...state, noPost: action.payload } }

        
        default: return { ...state }
    }
}