import React, { Component, Suspense, useEffect } from "react";
import withRouter from "./WithRouter";
import ErrorFound from "../ErrorFound";
import { FontAwesomeIcon } from "../../Assets/AssetsHelper";
import { Button, Alert } from "react-bootstrap";
import { connect } from "react-redux";
import { isCreatorsUser, isShopify, onBoardingSteps } from "../../utils"
import { getUserInfo } from "../../actions/loginActions";
import { getCookieValue } from "../../utils";
import OfferStrip from "../Layout/Main/CommonComponents/OfferStrip";
import { permissionDenied } from "./AccessDenied";
import ReviewModal from "../Layout/Main/CommonComponents/ReviewModal";
import { onLCP } from 'web-vitals';

const Aside = React.lazy(() => import("../Layout/Aside"));
const Header = React.lazy(() => import("../Layout/Header"));
const LoginBasePage = React.lazy(() => import("./loginBasePage"));
const Navigation = React.lazy(() => import("./Navigation"));
class RoutesExtends extends Component {
  constructor(props) {
    super(props);
    this.state = {
      offerVisible: false,
      offerAnimate: false
    }
    this.timeoutId = null;
  }

    sendToAnalytics = (metric) => {
    fetch('/analytics', {
      method: 'POST',
      body: JSON.stringify(metric),
      headers: { 'Content-Type': 'application/json' },
    });
  };

   reportWebVitals = (onPerfEntry) => {
    if (onPerfEntry && onPerfEntry instanceof Function) { 
      onLCP(onPerfEntry);
    }
  };

  
  componentDidMount() {
    const { navigate, authorized, getUserInfo } = this.props
    if (!authorized?.userData?.user_data && localStorage.getItem("token") && !window.location.pathname.includes("/Shopify/install") && !window.location.pathname.includes("/Shopify/token") && !window.location.pathname.includes("/collaborator/request")) getUserInfo(navigate);
    if (authorized?.userData?.user_data?.sessionData?.createFrom == 'shopify' && !window.location.pathname.includes("/accounts/price")) document.body.classList.add('shopify_active')
    if (!onBoardingSteps() && window.location.pathname.includes("/home")) { document.body.classList.add('onboarding_active') }
    else { document.body.classList.remove('onboarding_active') }

      this.timeoutId = setTimeout(() => {
          this.setState({ offerVisible: !getCookieValue('__offerAlert') })
       }, 5000);

      
      this.reportWebVitals((metric) => {
        console.log(metric,'metricmetricmetric'); // Log the metric details
        this.sendToAnalytics(metric); // Send the metrics to analytics
      });

   }

  componentWillUnmount() {
    if (this.timeoutId) {
      clearTimeout(this.timeoutId);
    }

  }

  render() {
    const { navigate, authorized, dashboarddata } = this.props
    const { offerVisible } = this.state

    if (isShopify() && !window.location.pathname.includes("/accounts/price")) document.body.classList.add('shopify_active')
    const isAnalytic = window.location.pathname.includes("/analytic")
    isAnalytic ? document.body.classList.add('analytics') : document.body.classList.remove('analytics')
    window.location.pathname.includes("/analytic-new") ? document.body.classList.add('analyticss') : document.body.classList.remove('analyticss')

    const withoutHeader = ["/paymentPaidCallback", "/price/success", "shopify/success", "/price/failed", "ugc_right"]
    const withoutAside = ["/product/switch", "/paymentPaidCallback", "/price/success", "shopify/success", "/price/failed", "/accounts/price", "ugc_right", "/onboarding", "/init/index",];


    let NoSubHeaderLinks = ["/products", "/home", "/onboarding", "/price", "/cancel", "/steps"];
    const withoutSubHeader = ["/transactions/cancel"];
    if (!isCreatorsUser()) NoSubHeaderLinks.push("/creators")

    var NoHeader = withoutHeader.some(path => window.location.pathname.includes(path)) ? true : false
    var NoSubheader = NoSubHeaderLinks.some(path => window.location.pathname.includes(path)) ? true : false
    var NoAside = withoutAside.some(path => window.location.pathname.includes(path)) ? true : false

    if (authorized?.userData?.user_data) {
      permissionDenied(authorized?.userData?.user_data, navigate)
    }

    if(!window.location.href.includes("website/publish")){
      const reviewHub = document.getElementById("subtree-container");
        if (reviewHub) {
          reviewHub.remove(); 
        }
    }

    if (!localStorage.getItem("token") || (localStorage.getItem("token") && localStorage.getItem("steps")) || (window.location.pathname.includes("/Shopify/install") || window.location.pathname.includes("/Shopify/token") || window.location.pathname.includes("/collaborator/request"))) {
      return <>
        {/* {window.location.pathname.includes("/accounts/price") && 
        <PricePlan authorized={authorized} />} */}
        <Suspense fallback={null}><LoginBasePage history={navigate} /></Suspense>
      </>
    }
    else {
      return <ErrorFound>
        <div className={`app-page d-flex flex-column flex-column-fluid flex-column align-items-stretch h-100${!NoSubheader ? ' has-subheader' : ''}${NoAside ? ' no-aside' : ''}${NoHeader ? ' no-header' : ''}`}>
          {!NoAside  && <Suspense fallback={null}><Aside /></Suspense>}
          {!NoHeader && <Suspense fallback={null}><Header navigate={navigate} authorized={authorized} /></Suspense>}
          {dashboarddata && Object.keys(dashboarddata).length > 0 ? <main className="main_content position-relative">
            <Suspense fallback={null}><Navigation history={navigate} authorized={authorized} /></Suspense>
            {!window.location.pathname.includes("/price") ?
              <Alert show={offerVisible} className={`offer_strip position-fixed p-4 rounded-pill mx-auto bg-body shadow-lg`}>
                <OfferStrip redirect={true} setCookie={!offerVisible} />
                <Button variant='icon' size='sm' className='rounded-circle border-0 position-absolute box-shadow bg-body' onClick={() => this.setState({ offerVisible: false })} style={{ top: -7, right: -7 }}><FontAwesomeIcon icon="xmark" /></Button>
              </Alert>
              : null}
              {localStorage.getItem('isReview') == 'true' && <ReviewModal/>}
          </main> : null}
        </div>
      </ErrorFound>
    }
  }
}

const mapStateToProps = (state) => {
  return {
    planLimitExceed: state.authorized?.planLimitExceed,
    dashboarddata: state.dashboardData?.dashboarddata,
  }
}
const mapDispatchToProps = dispatch => {
  return {
    getUserInfo: (navigate) => dispatch(getUserInfo(navigate)),

  }
}
export default connect(mapStateToProps, mapDispatchToProps)(withRouter(RoutesExtends));