import { CREATE_SHOPON_REDUCER, UPDATE_SHOPON_REDUCER, DELETE_SHOPON_REDUCER, ALL_SHOPON_LIST_REDUCER, GET_SHOPON_WALL_REDUCER, ACTIVE_SHOPON_REDUCER, GET_SHOPON_PRODUCT_REDUCER, LOADING_SHOPON_REDUCER, TOGGLE_ADD_SHOPON, SHOPON_BRAND_DATA_REDUCER, SHOPON_TITLE_REDUCER, SHOPON_DESCRIPTION_REDUCER, SHOPON_LOGO_REDUCER, SHOPON_TYPE_REDUCER, SHOPON_POST_REDUCER, SHOPON_PRODUCT_REDUCER } from './keys'
const initialState = {
    shopOnList: [],
    shopOnListLoader: true,
    wallData: [],
    productData: [],
    activeShopOn: '',
    loadingShopon: true,
    addShoponNew: false,
    brand: [],
    productSetting: [],
    after: [],
    customPost: []
}
export default function reducer(state = initialState, action) {
    switch (action.type) {
        case ALL_SHOPON_LIST_REDUCER: {
            return { ...state, shopOnList: action.payload, shopOnListLoader: false }
        }

        case CREATE_SHOPON_REDUCER: {
            return { ...state, shopOnList: [...state.shopOnList, action.payload] };
        }

        case ACTIVE_SHOPON_REDUCER: {
            return { ...state, activeShopOn: action.payload };
        }
        case SHOPON_BRAND_DATA_REDUCER: {
            return { ...state, brand: action.payload };
        }
        case SHOPON_TITLE_REDUCER: {
            var updateState = { ...state.brand, title: action.payload, name: action.payload }
            if (updateState.extra_data) updateState["extra_data"] = { ...updateState.extra_data, title: action.payload }
            return { ...state, brand: updateState };
        }
        case SHOPON_DESCRIPTION_REDUCER: {
            var updateState = { ...state.brand, description: action.payload }
            if (updateState.extra_data) updateState["extra_data"] = { ...updateState.extra_data, description: action.payload }
            return { ...state, brand: updateState };
        }
        case SHOPON_LOGO_REDUCER: {
            var updateState = { ...state.brand, logo: action.payload }
            if (updateState.extra_data) updateState["extra_data"] = { ...updateState.extra_data, logo: action.payload }
            return { ...state, brand: updateState };
        }
        case SHOPON_TYPE_REDUCER: {
            var updateState = { ...state.brand, type: action.payload }
            if (updateState.extra_data) updateState["extra_data"] = { ...updateState.extra_data, type: action.payload, theme_type: action.payload }
            return { ...state, brand: updateState };
        }
        case SHOPON_POST_REDUCER: {
            return { ...state, brand: { ...state.brand, type: action.payload } };
        }
        case SHOPON_PRODUCT_REDUCER: {
            return { ...state, brand: { ...state.brand, type: action.payload } };
        }


        case UPDATE_SHOPON_REDUCER: {
            const { id, responseData } = action.payload
            const updatedWebsiteData = state.shopOnList.filter((x) => x.id == id);
            updatedWebsiteData[0] = responseData;
            return { ...state, shopOnList: state.shopOnList.map((x) => x.id == id ? updatedWebsiteData[0] : x) };
        }
        case DELETE_SHOPON_REDUCER: {
            const updatedWebsiteData = state.shopOnList.filter((x) => x.id != action.payload);
            return { ...state, shopOnList: updatedWebsiteData };
        }

        case GET_SHOPON_WALL_REDUCER: {
            return { ...state, wallData: action.payload?.postData, customPost: action.payload?.customPost, after: action.payload?.after, productSetting: action.payload?.productSetting }
        }
        case GET_SHOPON_PRODUCT_REDUCER: {
            return { ...state, productData: action.payload }
        }
        case LOADING_SHOPON_REDUCER: { return { ...state, loadingShopon: action.payload } }
        case TOGGLE_ADD_SHOPON: { return { ...state, addShoponNew: action.payload } }


        default:
            return { ...state }
    }

}