import { PLAN_LIMIT_EXCEED, USER_AUTHENTICATED_LOGIN, USER_TOKEN } from './keys'

const initialState = { 
    user: null, 
    userData:null,
    planLimitExceed: false,
    gallery_views_limit: null
}

export default function reducer(state = initialState, action) {
    switch (action.type) {
        case USER_AUTHENTICATED_LOGIN: {
            return { ...state, userData: {user_data :action.payload} }
        }
        case USER_TOKEN: {
            return { ...state, token: action.payload }
        }
        case PLAN_LIMIT_EXCEED: {
            return {...state, planLimitExceed: action.payload, gallery_views_limit: action.gallery_views_limit }
        } 
        default:
            return { ...state }
    }

}