import React from 'react';
import ReactDOM from 'react-dom';
import { Provider } from 'react-redux'
import store from './store';
import { BrowserRouter } from "react-router-dom";
import isEqual from 'lodash/isEqual';
import App from './app/App';

ReactDOM.render(
  <React.StrictMode>
    <Provider store={store} >
      <React.Suspense>
        <BrowserRouter basename='/'>
          <App />
        </BrowserRouter>
      </React.Suspense>
    </Provider>
  </React.StrictMode>,
  document.getElementById('rootDashoard')
);


let prevWallData = null;
let prevShopOnData = null;

store.subscribe(() => {
  const wallData = store.getState().appData;
  const clonePostValue = localStorage.getItem('website_id') == '12976' ? { clonePost: 0 } : {};

  const payload = { wall: { ...wallData?.wall, Personalization: { ...wallData?.wall?.Personalization, ...clonePostValue } }, postData: wallData?.post_data ? wallData?.post_data : [], after: wallData?.after ? wallData?.after : '', customPost: wallData?.custom_post ? wallData?.custom_post : [] }

  let checkWebsiteExist = setInterval(function () {
    const websiteLivePreview = document.getElementById("websiteLivePreview");
    if (websiteLivePreview && !isEqual(payload, prevWallData)) {
      prevWallData = { ...payload };
      const uniqueID = Math.random().toString(36).substr(2, 9);
      const message = {
        data: JSON.stringify({
          ...payload,
          uniqueID
        }), type: 'reloadWebsite'
      };
      websiteLivePreview?.contentWindow?.postMessage(message, '*');

    }

    var preWebsitePayload = null
    window.addEventListener('message', (e) => {
      if (e && e.data && e.data.type === "sreloadWebsite" && !isEqual(e.data, preWebsitePayload)) {
        preWebsitePayload = e.data
        const message = {
          data: JSON.stringify({
            ...payload
          }), type: 'reloadWebsite'
        };
        websiteLivePreview?.contentWindow?.postMessage(message, '*');
      }
    });
    clearInterval(checkWebsiteExist);
  }, 100);




  const shopOnData = store.getState().shopOnList;
  const ShopOnPayload = { brand: { type: shopOnData?.brand?.extra_data?.theme_type || 1, logo: shopOnData?.brand?.extra_data?.profile || null, title: shopOnData?.brand?.name, description: shopOnData?.brand?.extra_data?.description || '' }, slug: shopOnData?.brand?.slug, postData: shopOnData?.wallData, productSetting: shopOnData?.productSetting, products: shopOnData?.productData, after: shopOnData?.after, customPost: shopOnData?.customPost }

  let checkExist = setInterval(function () {
    const iframeId = document.getElementById("shopOnBioPreview");
    const iframeId2 = document.getElementById("shopOnBioPreview2");
    if ((iframeId || iframeId2) && !isEqual(ShopOnPayload, prevShopOnData)) {
      prevShopOnData = ShopOnPayload;
      const message = { data: JSON.stringify(ShopOnPayload), type: 'reloadShopOn' };
      iframeId?.contentWindow?.postMessage(message, '*');
      iframeId2?.contentWindow?.postMessage(message, '*');
    }

    var prePayload = null
    window.addEventListener('message', (e) => {
      if (e && e.data && e.data.type === "sreloadShopOn" && !isEqual(e.data, prePayload)) {
        prePayload = e.data
        const message = { data: JSON.stringify(ShopOnPayload), type: 'reloadShopOn' };
        iframeId?.contentWindow?.postMessage(message, '*');
        iframeId2?.contentWindow?.postMessage(message, '*');
      }
    });
    clearInterval(checkExist);
  }, 100);


});