import { DELETE_COLLABORATOR, EDIT_COLLABORATOR, GET_COLLABORATOR_LIST } from "./keys";

const initialState = {
    collaboratorList: []
}

export default function reducer(state = initialState, action){
    const { type, payload, id } = action;
    switch(type){
        case GET_COLLABORATOR_LIST:
            return { ...state, collaboratorList: payload}
        
        case DELETE_COLLABORATOR:
            const newCollaboratorList = state.collaboratorList.filter(collaborator=> String(collaborator.id) != String(id))
        return {...state, collaboratorList: newCollaboratorList}

        case EDIT_COLLABORATOR:
            const updateCollaboratorList = [];
            for (let collaborator of state.collaboratorList) {
                if (collaborator.id === payload.id) {
                    id == 1 ? collaborator.role = 1 : collaborator.status = payload.status == 1 ? 0 : 1 ;
                }
                updateCollaboratorList.push(collaborator);
            }
            return { ...state, collaboratorList: updateCollaboratorList }
        
        default:
            return state
    }
}