import { IS_API_ACCESS_LIVE } from "../actions/api";

const cloudTbUrl = 'https://cloud.tagshop.ai/app/'
const urlFrom = IS_API_ACCESS_LIVE ? cloudTbUrl : process.env.PUBLIC_URL + '/assets/'
export const baseUrl = pathname => urlFrom + pathname;

export const cloudUrl = pathname => cloudTbUrl + pathname;

export const FontAwesomeIcon = ({ type, icon, size, iconClass }) => <i className={`${type ? `fa-${type}` : `fa-regular`} fa-${icon} ${iconClass?iconClass:''}`} style={{fontSize:size}}></i>

export const ImagePlaceholder = baseUrl(`media/images/error/image.svg`);

export const ProductPlaceholder = baseUrl(`media/images/error/no-product.svg`);