import {  GET_BIGCOMMERCE_DATA } from "./keys";
const initialState = {
    BigcommerceData:  null 
    }
export default function reducer(state = initialState, action) {
    switch (action.type) {
        case GET_BIGCOMMERCE_DATA: {
            return { ...state, BigcommerceData: action.payload }
        }
      
        default:
            return { ...state }
    }

}

 