import { DELETE_NOTIFICATION, GET_ALL_NOTIFICATION, GET_LATEST_NOTIFICATION, MARK_ALL_AS_READ } from "./keys";


const initialState={
    notificationList:[], 
    notificationListLength:0
}
export default function reducer(state=initialState,action){
    switch (action.type) {
        case GET_ALL_NOTIFICATION: {
            const {notifications,count} = action.payload;
            return { ...state, notificationList: notifications,notificationListLength:count }
        }

        case DELETE_NOTIFICATION: {
            const id = action.payload;
            const updateNotificationList = state.notificationList.filter((notification)=>notification.id!==id);
            return {...state, notificationList:updateNotificationList,notificationListLength:state.notificationListLength-1}
        }

        default:
            return { ...state }
    }
}
