import { CREATE_WEBSITE_REDUCER, UPDATE_WEBSITE_REDUCER, ALL_WEBSITE_LIST_REDUCER, DELETE_WEBSITE_REDUCER, ACTIVE_WEBSITE_ID_REDUCER, LOADING_WEBSITE_REDUCER , TOGGLE_ADD_WEBSITE, UPDATE_WEBSITE_UTM_TRACKER} from './keys'
const initialState = { 
    websiteList: [],
    activeWebsite_id:'',
    websiteLoading:false,
    addWebsiteNow:false
}
export default function reducer(state = initialState, action) {
    switch (action.type) {
        case ALL_WEBSITE_LIST_REDUCER: {
            return { ...state, websiteList: action.payload }
        }

        case CREATE_WEBSITE_REDUCER: { 
            return { ...state, websiteList: [...state.websiteList, action.payload] };
          }
           case ACTIVE_WEBSITE_ID_REDUCER:{
               return { ...state, activeWebsite_id:action.payload }
           }
        case UPDATE_WEBSITE_REDUCER:{
           const {id, name} = action.payload
           const updatedWebsiteData = state.websiteList.filter((x) => x.wall.Wall.id == id); 
           updatedWebsiteData[0].wall.Wall.name = name;
        return { ...state,  websiteList: state.websiteList.map((x) =>  x.wall.Wall.id == id ? updatedWebsiteData[0] : x ) }; 
        }
        case DELETE_WEBSITE_REDUCER:{ 
            const updatedWebsiteData = state.websiteList.filter((x) => x.wall.Wall.id != action.payload);  
         return { ...state,  websiteList: updatedWebsiteData }; 
         }

         case LOADING_WEBSITE_REDUCER: { return { ...state, websiteLoading: action.payload }; }
       
         case TOGGLE_ADD_WEBSITE: { return { ...state, addWebsiteNow: action.payload }; }

         case UPDATE_WEBSITE_UTM_TRACKER :{ 
             const {id, google_tacking_code, google_tacking_status, utm_status, utm_source, utm_campaign, utm_medium }=action.payload  
             const updatedWebsiteData = state.websiteList.filter((x) => x.wall.Wall.id == id); 
             updatedWebsiteData[0].wall.Wall.google_tacking_code = google_tacking_code;
             updatedWebsiteData[0].wall.Wall.google_tacking_status = google_tacking_status;
             updatedWebsiteData[0].wall.Wall.utm_status = utm_status;
             updatedWebsiteData[0].wall.Wall.utm_source = utm_source;
             updatedWebsiteData[0].wall.Wall.utm_campaign = utm_campaign;
             updatedWebsiteData[0].wall.Wall.utm_medium = utm_medium;
          return { ...state,  websiteList: state.websiteList.map((x) =>  x.wall.Wall.id == id ? updatedWebsiteData[0] : x ) }; 
         }
        
        default:
            return { ...state }
    }

}