import { ConversionData } from '../../utils/demoAnalyticsData'
import {  CONVERSION_RECORDS_DATA, CONVERSION_RECORDS_LOADER, CONVERSION_BREACKDOWN_DATA, CONVERSION_BREACKDOWN_LOADER,  } from '../keys'

const initialState = { 
    conversion_data: ConversionData, 
    conversion_loader: true,  
    conversion_breackDown_loader: true,
     conversion_breackDown_data: [], 
    }

export default function reducer(state = initialState, action) {
    switch (action.type) {

        case CONVERSION_RECORDS_DATA: { return { ...state, conversion_data: action.payload } }
        case CONVERSION_RECORDS_LOADER: { return {...state, conversion_loader: action.payload} } 

        case CONVERSION_BREACKDOWN_DATA: { return { ...state, conversion_breackDown_data: action.payload } }
        case CONVERSION_BREACKDOWN_LOADER: { return {...state, conversion_breackDown_loader: action.payload} } 

        default: return { ...state }
    }
}