import { AUTO_MOD_LIST, GET_GOOGLE_TRACKING_ID, APPS_MORE_HASTAG_HIGHLIGHTER, GET_FONTS, ACTIVE_VIDEO_POPUP, GET_CTA_STATUS, GET_CUSTOM_CSS_STATUS, THEME_UPDATE, CUSTOME_POST_NETWORK_LIST, AUTOMODERATION_POST_LIST } from './keys'
const initialState = { detail: null, autoModList: null, fonts: null, ctaStatus: false, netWorkList: [] }
export default function reducer(state = initialState, action) {


    switch (action.type) {
        case GET_FONTS: {
            return { ...state, fonts: action.payload }
        }
        case GET_GOOGLE_TRACKING_ID: {
            return { ...state, googleTracking: action.payload }
        }
        case GET_CTA_STATUS: {
            return { ...state, data: state.detail?.wall && (state.detail.wall.Personalization.ctaStatus = action.payload ? 1 : 0) }
        }
        case ACTIVE_VIDEO_POPUP: {
            return { ...state, video_popup: action.payload }
        }
        case GET_CUSTOM_CSS_STATUS: {
            return { ...state, data: state.detail?.wall && (state.detail.wall.Personalization.cssStatus = action.payload ? 1 : 0) }
        }
        case THEME_UPDATE: {
            return { ...state, data: state.detail.data.wall.Personalization.commerceTheme = action.payload }
        }
        case AUTO_MOD_LIST: {
            return { ...state, autoModList: action.payload }
        }

        default:
            return { ...state }
    }

}