export const fetchProductList = (page = 0, showPost = 10, tag = "", search = "", callBack, referenceId, newMedia) => {
    var Imgurl = newMedia ? encodeURIComponent(newMedia) : '';
    var data = `?page=${page - 1}&perPage=${showPost}&tag=${tag}&q=${search}&postId=${referenceId ? referenceId : ''}&imageUrl=${Imgurl}`
    return (dispatch) => {
        dispatch({ type: LOADING_TAG_PRODUCTS, payload: true });
        new HttpClient().get(`${PRODUCT_LIST}${data}`).then((response) => {
            const { productCount, allProducts } = response.data.responseData
            dispatch({ type: DISPATCH_PRODUCT_LIST, payload: { allProducts: allProducts, productCount: productCount } });
            dispatch({ type: LOADING_PRODUCTS, payload: true });
            dispatch({ type: LOADING_TAG_PRODUCTS, payload: false });

            callBack(allProducts);
        }).catch((error) => {
            dispatch({ type: LOADING_TAG_PRODUCTS, payload: false });
            console.log("ERROR", error)
            callBack([]);
        })
    }
}



export const ACTION_PRODUCT_LIST_FORTAG = (page, showPost, tag, search, callBack, referenceId, newMedia) => {
    var data = `?page=${page - 1}&perPage=${showPost}&tag=${tag}&q=${search}&postId=${referenceId ? referenceId : ''}&imageUrl=${newMedia ? newMedia : ''}`


    return (dispatch) => {
        new HttpClient().get(`${PRODUCT_LIST}${data}`).then(({ data: { responseCode, responseData, responseMessage } }) => {
            if (responseCode === 200) {
                const { allProducts, productCount, getProductIds } = responseData
                dispatch({ type: DISPATCH_PRODUCT_LIST_FOR_TAG, payload: { allProducts: allProducts, productCount: productCount, getProductIds: getProductIds }, });
                callBack(allProducts);
            }
            
        }).catch((error) => {
            console.log("ERROR", error)
            callBack([]);
        })
    }
}


export const ACTION_PRODUCT_ADD = (obj, callBack) => {
    return (dispatch) => {
        new HttpClient().post(`${PRODUCT_ADD}`, obj).then((detailReponse) => {
            const { responseData, responseMessage, responseCode } = detailReponse.data;
            dispatch({ type: DISPATCH_PRODUCT_ADD, payload: responseData });
            TOAST_SUCCESS(responseMessage)
            callBack()
        }).catch((ex) => {
            const { responseMessage } = ex.response.data
            TOAST_ERROR(responseMessage ? responseMessage : "Something went wrong, please try again later.")
            callBack()
        })
    }
}

