export const ACTION_PRODUCT_DELETE = (obj, callBack) => {
    return (dispatch) => {
        new HttpClient().post(PRODUCT_DELETE, obj).then(res => {
            const { responseMessage, responseCode, responseStatus } = res.data

            TOAST_DISMISS()
            if (responseCode == 200) {
                TOAST_SUCCESS(responseMessage)
                dispatch({ type: DISPATCH_PRODUCT_REMOVE, payload: obj.id })
                callBack('delete')
            }
            else TOAST_ERROR(responseMessage ? responseMessage : 'Something went worng!')
        }).catch(err => console.log(err))
    }
}

export const IMPORT_CSV_PRODUCT = (obj, callback, countAllPage, fromOB = false, navigate) => {
    const toastId = TOAST_LOADING();
    try {
        new HttpClient().post(PRODUCT_IMPORT, { 'csv_url': obj }).then(res => {
            const { responseCode, responseMessage } = res.data
            if (responseCode == 200) {
                TOAST_UPDATE(toastId, "success", responseMessage)
                if (fromOB) navigate(`/content/moderation/${localStorage.getItem('wallId') ? localStorage.getItem('wallId') : ''}?ob_success=true`)
                countAllPage();
            }
            else TOAST_UPDATE(toastId, "error", responseMessage)
            callback()
        }).catch(err => {
            const { data } = err?.response
            if (data && Object.keys(data).length > 0) TOAST_UPDATE(toastId, "error", data?.responseMessage)
        })
    }
    catch (error) {
        TOAST_UPDATE(toastId, "error", "something went wrong!")
    }
}



export const GET_SHOPIFY_ACCOUNT = () => {
    var obj = new FormData()
    obj.append("wallId", localStorage.getItem('wallId'))
    return (dispatch) => {
        new axios.post(`${BASE_URL}/shopify/getPublish`, obj, { withCredentials: false })
            .then((response) => {
                const { status, data } = response.data;
                dispatch({
                    type: GET_SHOPIFY_DATA,
                    payload: data,
                });
            }).catch((error) => {
                console.log("ERROR", error)
            });
    }
}

