export const CONNECT_SHOPIFY_STORE = (shopURL) => {
    if (!localStorage.getItem('shopifyLogin')) {
        var newShopUrl = shopURL
        if (newShopUrl.includes('https://')) newShopUrl = newShopUrl.replace('https://', '')
        if (newShopUrl.includes('http://')) newShopUrl = newShopUrl.replace('http://', '')
        new HttpClient().get(`${SHOPIFY_GUEST_CONNECT_NODE}?wallID=${localStorage.getItem('wallId')}&shopurl=${newShopUrl}`).then(res => {
            const { data, message, response } = res.data
            window.location.href = data
        }).catch(error => {
            TOAST_ERROR('Something went wrong!')
        })
    } else {
        TOAST_ERROR('Something went wrong!')
    }
}

