export const SHOPIFY_PRODUCT_SYNC = (store_id, callBack) => {
    let toastId = null
    if (window.location.href.includes("content/products")) toastId = TOAST_LOADING()
    new HttpClient().post(`${SHOPIFY_SYNC_PRODUCT}/${store_id}`).then(res => {
        if (window.location.href.includes("content/products")) TOAST_DISMISS(toastId)
        if (res.data.status) {
            if (window.location.href.includes("content/products")) TOAST_UPDATE(toastId, "success", res.data.success)
            callBack()
        }
        else {
            callBack()
            TOAST_DISMISS(toastId)
        }
    }).catch(err => {
        callBack()
        console.log('err', err)
        TOAST_DISMISS(toastId)
    })
}

export const SYNC_MAGENTO_PRODUCTS = (id, accessToken, magentourl, callback) => {
    new HttpClient().post(MAGENTO_GUEST_SYNC, { storeId: id, accessToken, magentourl }).then(res => {
        const { status, data } = res.data
        if (status && data.categories) {
            const payload = {
                storeId: id,
                catgoeries_id: data.categories[0].id,
                catgoeries_name: data.categories[0].name,
                currency_code: data.currency_code,
                currency_symbol: data.currency_symbol,
                accessToken,
                magentourl,
                wallId: localStorage.getItem('wallId')
            }

            new HttpClient().post(MAGENTO_GUEST_SYNC_PRODUCT, payload).then(res => {
                const { status, type, message } = res.data
                if (status) callback()
                else callback(message)
            }).catch(error => {
                callback(error)
            })

        }
    }).catch(error => {
        TOAST_DISMISS()
    })
}

