export const GUEST_WOOCOMMERCE_ADD = (obj) => {
    const toastId = TOAST_LOADING()
    let newUrl = obj
    const regex = /^(http:\/\/|https:\/\/).+/;
    if (!regex.test(newUrl)) {
        newUrl = `https://${obj}`
    }
    new HttpClient().post(`${ADD_WOOCOMMERCE_SHOP}`, { url: newUrl }).then(res => {
        const { message, status, data } = res.data
        if (data) {
            TOAST_DISMISS(toastId)
            window.location.replace(`${data}`);
        }
        else if (status == 'error') TOAST_UPDATE(toastId, "error", message)
        else TOAST_UPDATE(toastId, "error", "Something went wrong!")
    }).catch(error => {
        TOAST_UPDATE(toastId, "error", "Something went wrong!")
    })
}

