import { SHOW_POP_UP, CLOSE_POP_UP, SHOW_HOTSPOT, SET_MEDIA_SIZE } from "../keys" 
const initialState = { isShowPopUpEditor: false, data: null, showHotspot: null, index: null, showAll: false, hotspotId: null, mediaHeight: 0, mediaWidth: 0 }
export default function reducer(state = initialState, action) {
    switch (action.type) {
        case SHOW_POP_UP: {
            return { ...state, isShowPopUpEditor: true, data: action.payload }
        }
        case CLOSE_POP_UP: {
            return { ...state, isShowPopUpEditor: false, data: null }
        }
        case SHOW_HOTSPOT: {
            return { ...state, ...action.payload}
        }
        case SET_MEDIA_SIZE: {
            return { ...state, ...action.payload}
        }
        default:
            return { ...state }
    }

}