import React, { Component } from 'react';
import { Button } from 'react-bootstrap';
import { COPY_TO_CLIPBOARD } from '../../../../utils';
import Swal from 'sweetalert2'
import withRouter from '../../../routes/WithRouter';

class OfferStrip extends Component {
       state = { copied: false }
       copyText = (id) => {
              COPY_TO_CLIPBOARD(id)
              Swal.fire({
                     title: 'Code copied!',
                     text: `Next: Choose your plan and proceed to checkout. ✨`,
                     icon: 'success',
              }).then((result) => {
                     if (this.props.redirect && result.isConfirmed) {
                            this.props.navigate('/price')
                     }
              });
              this.setState({ copied: true })
              setTimeout(() => { this.setState({ copied: false }) }, 1000)
       }

       setCookie = (name, value, days) => {
              let expires = "";
              if (days) {
                     const date = new Date();
                     date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
                     expires = "; expires=" + date.toUTCString();
              }
              document.cookie = name + "=" + (value || "") + expires + "; path=/";
       }
       componentDidUpdate(){
              if (this.props.setCookie)this.setCookie('__offerAlert', '1', 10)
       }
       render() {
              return (
                     <div className='text-center f-center flex-wrap'>
                            <span className='mx-3 d-inline-block' style={{ padding: 5 }}>Hurry! Black Friday {`>`} 50 Days!⏳SAVE 20% on Tagshop!</span>
                            <Button className='rounded-pill' onClick={() => this.copyText('c_code_')}>{<span>Use Code: <span id="c_code_" className='fw-bold' style={{ userSelect: 'auto' }}>SHOP20</span></span>}</Button>
                     </div>
              );
       }
}

export default withRouter(OfferStrip);