
import axios from 'axios';
import { HOST_URL } from './api'

const conditions = ['profile', 'transactions', 'notifications'];
const path = window.location.pathname;

const getToken = (config) => {
    if (!(config.url.includes("userInfo"))) {

        return localStorage.getItem('token');
    }
    return localStorage.getItem('token') ? localStorage.getItem('token') : localStorage.getItem('shared_token');
}

const requestInterceptor = (config) => {
    var headers = {}
    headers = {
        'authorization': `Bearer ${getToken(config)}`,
        'ownerId': localStorage.getItem('ownerId'),
        'loginOwnerId': localStorage.getItem('loginOwnerId'),
    }

    return {
        ...config,
        headers: { ...config.headers, ...headers },
    }
};

class HttpClient {
    constructor() {
        const options = { baseURL: HOST_URL };
        const instance = axios.create(options);
        instance.interceptors.request.use(requestInterceptor);
        axios.interceptors.response.use(
            function (response) {
                return response;
            },
            function (error) {
                return Promise.reject(error);
            }
        );
        return instance;
    }
}
export default HttpClient;
