import { combineReducers } from "redux"

import authorized from './authReducer'
import dashboardReducer from './dashboardReducer'
import homeStepReducer from './HomeStepReducer'
import accountReducer from './accountReducer'
import moderation from './moderationReducer'
import loaderReducer from './loaderReducer'
import ctaReducer from './ctaReducer'
import fontReducer from './fontReducer'
import addFeedReducer from './addFeedReducer'
import manageFeedsReducer from './manageFeedsReducer'
import publishReducer from './publishReducer'
import themeReducer from './themeReducer'
import modalReducer from './show_modal_section'
import appsMore from "./appsMore";
import notification from './notification';
import signUp from './signUp';
import planPriceDetail from './planPriceReducer';
import products from './productsCatalogReducer';
import StripeRequest from './stripeReducer';
import ShopifyData from './shopifyReducer';
import BigcommerceData from './bigcommerceReducer';
import websiteList from './websiteReducer';
import emailList from './emailReducer';
import shopOnList from './shoponReducer'
import shopOnUserData from './shopOnUserReducer'

//------ANALYTICS------  
import overViewReducer from './analytics/overViewReducer'
import contentGalleryReducer from './analytics/contentGalleryReducer'
import conversionReducer from './analytics/conversionReducer'
import websiteReducer from './analytics/websiteReducer'
import shopOnReducer from './analytics/shopOnReducer'

//------THEMES PREVIEW------  
import appData from './themes/appDataReducer'
import modalPop from './themes/modalPopReducer'
import loaderData from './themes/loaderReducer'
import collaborator from './collaborator'
import limitExceed from './limitExceed'


export default combineReducers({
    authorized: authorized,
    dashboardData: dashboardReducer,
    homeStepData:homeStepReducer,
    userAccountData:accountReducer,
    moderation,
    loader: loaderReducer,
    ctaData:ctaReducer,
    allFont:fontReducer,
    addFeedReducer,
    modalReducer,
    manageFeeds: manageFeedsReducer,
    allTags:publishReducer,
    allTags:publishReducer,
    themeData:themeReducer,
    appsMore,
    notification,
    signUp,
    planPriceDetail,
    products,
    StripeRequest,
    ShopifyData,
    BigcommerceData,
    websiteList,
    emailList,
    shopOnList,
    shopOnUserData,


    analyticsOverView:overViewReducer,
    analyticsContentGallery:contentGalleryReducer,
    analyticsConversion:conversionReducer,
    analyticsWebsite:websiteReducer,
    analyticsShopOn:shopOnReducer,

    
    appData,
    modalPop,
    loaderData,
    collaborator,
    limitExceed
})

