import { GET_ALL_FONTS } from "./keys";
const initialState={
    allFonts:null,
    fonts:[]
}

export default function  reducer(state=initialState, action){
    switch(action.type){
        case GET_ALL_FONTS:
            return{...state, allFonts:action.payload, fonts:fontReformat(action.payload)}
        default:
            return{...state}
    }
}

const fontReformat=(data)=>{
     var font =[]
     font = data ? data.map((item)=>{
          return({ label : item.family, value : item.id ,  font: item.family })
     }):''
     return font;
}