import { getUserInfo } from "../actions/loginActions";
import { DELETE_EXTRA_LIMITS, SET_EXTRA_LIMITS } from "./keys";
import store from "../store";

const initialState = {
    extraPosts : 0,
    extraProducts : 0,
}

export default function reducer(state = initialState, action ){
    switch(action.type){
        case SET_EXTRA_LIMITS:{
            const { delete_posts, delete_tagged_products } = action.payload
            return {...state, extraPosts: delete_posts, extraProducts: delete_tagged_products}
        }

        case DELETE_EXTRA_LIMITS:{
            const  {posts, products, navigate} = action.payload
            if(state.extraPosts - posts == 0 && state.extraProducts - products == 0) store.dispatch(getUserInfo(navigate))
            return {...state, extraPosts: state.extraPosts- posts, extraProducts: state.extraProducts - products}
            
        }

        default:{
            return {...state}
        }
    }
}