import React, { Component, Suspense } from "react";
import { connect } from 'react-redux';
import { GET_ALL_FONT_ACTION } from '../actions/sceneActions'
import Routes from "./routes";
import { ToastContainer } from 'react-toastify';
import '@uppy/core/dist/style.min.css';
import '@uppy/dashboard/dist/style.min.css';
import '@uppy/drag-drop/dist/style.min.css';
import '@uppy/status-bar/dist/style.min.css';
import '@uppy/webcam/dist/style.min.css';
import 'react-toastify/dist/ReactToastify.css';
import 'bootstrap-daterangepicker/daterangepicker.css';
import '../Assets/scss/root.scss';
import '../App.css';
const HeaderScript = React.lazy(() => import("./routes/HeaderScript"));

class App extends Component {
  componentDidMount() {
    this.props.GET_ALL_FONT_ACTION();
  }
  render() {
    return <>
     
      <Routes {...this.props} />
      <ToastContainer position="bottom-right" autoClose={5000} hideProgressBar newestOnTop={false} closeOnClick rtl={false} pauseOnFocusLoss draggable pauseOnHover />
      <Suspense fallback={<></>}><HeaderScript /></Suspense>
    </>
  }
}

const mapStateToProps = state => {
  return {
    authorized: state.authorized,
    homeData: state.dashboardData?.dashboarddata,
  }
}

const mapDispatchToProps = dispatch => {
  return {
    GET_ALL_FONT_ACTION: () => dispatch(GET_ALL_FONT_ACTION()),
  }
}
export default connect(mapStateToProps, mapDispatchToProps)(App);