import { GET_SHOPIFY_DATA,  SHOPIFY_LOADER_REQUESTING } from "./keys";
const initialState = {
    ShopifyData: null,
    isRequesting: true,
}
export default function reducer(state = initialState, action) {
    switch (action.type) {
        case GET_SHOPIFY_DATA: {
            return { ...state, ShopifyData: action.payload }
        } case SHOPIFY_LOADER_REQUESTING: {
            return { ...state, isRequesting: action.payload }
        }

        default:
            return { ...state }
    }

}
