import {  DISPATCH_PRODUCT_LIST, DISPATCH_PRODUCT_ADD, DISPATCH_PRODUCT_UPDATE, DISPATCH_PRODUCT_REMOVE, DISPATCH_SHOPIFY_STORES_LIST, DISPATCH_SHOPIFY_STORES_DELETE, LOADING_PRODUCTS , SEARCH_BY_PRODUCTS, DISPATCH_PRODUCT_LIST_FOR_TAG, LOADING_TAG_PRODUCTS} from "./keys";
const initialState = { allProducts: null, connectedStores: null , loadingProd_cat:false , total_pages:0, searchText:'', searchProducts:[], loadingTagProduct:false}
export default function reducer(state = initialState, action) {
    switch (action.type) {
        case DISPATCH_PRODUCT_LIST: { 
            return { ...state, allProducts: action.payload.allProducts , searchProducts: action.payload.allProducts, total_pages: Math.ceil(action.payload.productCount/10) }
        }

        case  DISPATCH_PRODUCT_LIST_FOR_TAG:{
            return { ...state, searchProducts:[...state.searchProducts, ...action.payload.allProducts] , total_pages: Math.ceil(action.payload.productCount/10)}
        }

        case DISPATCH_PRODUCT_ADD: {
            return { ...state, allProducts: [action.payload,...state.allProducts] } 
        }

        case DISPATCH_PRODUCT_REMOVE: {
            const removedId = String(action.payload).includes(',') ? String(action.payload).split(",") : action.payload
            const remProduct = state.allProducts.filter(p => !String(removedId).includes(String(p.id))) 

            return { ...state, allProducts: remProduct}
        }

        case DISPATCH_PRODUCT_UPDATE: { 
            const updatedList = state.allProducts.map(p => {
                if(p.id == action.payload.id){

                    return{
                        "id": action.payload.id,
                        "filename": p.filename,
                        "product_title": action.payload.title,
                        "product_price": action.payload.price,
                        "price_currency_symbol": action.payload.priceCurrencySymbol,
                        "discount_currency_symbol": action.payload.discountCurrency,
                        "price_currency": action.payload.priceCurrency,
                        "discount_currency": action.payload.discountCurrency,
                        "product_discount": action.payload.discount,
                        "product_url": action.payload.url,
                        "product_image": action.payload.image,
                        "product_owner": p.product_owner,
                        "product_status": p.product_status,
                        "product_sku": action.payload.sku,
                        "shopify_product_id": action.payload.shopify_product_id,
                        "shopify_product_type": action.payload.shopify_product_type,
                        "tags": action.payload.shopify_product_tags,
                        "recomended": p.recomended
                    }
                }
                else return p
            })
            return { ...state, allProducts: updatedList } 
        }

        case DISPATCH_SHOPIFY_STORES_LIST: {
            return {...state, connectedStores: action.payload}
        }
        case LOADING_PRODUCTS: { return {...state, loadingProd_cat: action.payload} }
        case SEARCH_BY_PRODUCTS: { return {...state, searchText: action.payload} }
        case LOADING_TAG_PRODUCTS :{ return {...state, loadingTagProduct: action.payload} }

        case DISPATCH_SHOPIFY_STORES_DELETE: {
            const list = state.connectedStores.length && state.connectedStores.filter(l => l.id != action.payload) 
            return {...state, connectedStores: list}
        }
          default:
            return { ...state }
    }

}
